import{_ as t,o,c as r,ag as a}from"./chunks/framework.ePeAWSvT.js";const h=JSON.parse('{"title":"ADR-0001: LLM Mode 记忆系统 — categories + wiki-links 取代 Neo4j 语义节点","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-llm-mode-memory.md","filePath":"adr/0001-llm-mode-memory.md"}'),i={name:"adr/0001-llm-mode-memory.md"};function n(d,e,l,s,m,c){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="adr-0001-llm-mode-记忆系统-—-categories-wiki-links-取代-neo4j-语义节点" tabindex="-1">ADR-0001: LLM Mode 记忆系统 — categories + wiki-links 取代 Neo4j 语义节点 <a class="header-anchor" href="#adr-0001-llm-mode-记忆系统-—-categories-wiki-links-取代-neo4j-语义节点" aria-label="Permalink to &quot;ADR-0001: LLM Mode 记忆系统 — categories + wiki-links 取代 Neo4j 语义节点&quot;">​</a></h1><ul><li><strong>状态</strong>：Accepted</li><li><strong>日期</strong>：2026-07-08，修订 2026-07-10（PR #477 评审：检索去 LLM 化、零基础设施约束；二次修订：撤销双模开关，收敛为单管线 + embedding 渐进增强；三次修订：磁盘无不可读真相——索引不落盘，SQLite 移出设计，补可观测性；四次修订：向量不进物理内存——memmap + 量化分层，VectorIndex 可插拔端口（借鉴 mem0），vectors.json 作废改 .npy）</li><li><strong>关联</strong>：<a href="https://github.com/XnneHangLab/XnneHangLab/issues/471" target="_blank" rel="noreferrer">#471</a> / <a href="https://github.com/XnneHangLab/XnneHangLab/issues/468" target="_blank" rel="noreferrer">#468</a>（设计来源）、<a href="https://github.com/XnneHangLab/XnneHangLab/issues/470" target="_blank" rel="noreferrer">#470</a> / <a href="https://github.com/XnneHangLab/XnneHangLab/issues/469" target="_blank" rel="noreferrer">#469</a>（后续：Multi-Character 记忆）、<a href="./0002-memu-design-not-dependency.html">ADR-0002</a></li></ul><h2 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h2><p>memory_bench 的 Neo4j 图目前有 10 种节点类型，但只支撑可视化，不具备检索能力。其中语义层节点（Domain / Topic / Scene / Predicate）本质上是分类标签：</p><ul><li>白名单式 predicate / entity_type 不灵活，新场景要改 schema</li><li>每次记忆写入都要走 claim 抽取 → 图谱管线，维护成本高</li><li>图结构对 LLM 检索并不友好——LLM 更擅长读文本目录和跟随链接，而不是遍历图</li></ul><h2 id="决策" tabindex="-1">决策 <a class="header-anchor" href="#决策" aria-label="Permalink to &quot;决策&quot;">​</a></h2><p>引入 <strong>LLM Mode</strong>：扁平存储 + categories 分类 + wiki-links 跨类关联，取代 Neo4j 语义节点。</p><h3 id="硬性约束-2026-07-10-评审补充-见-pr-477-评论" tabindex="-1">硬性约束（2026-07-10 评审补充，见 PR #477 评论） <a class="header-anchor" href="#硬性约束-2026-07-10-评审补充-见-pr-477-评论" aria-label="Permalink to &quot;硬性约束（2026-07-10 评审补充，见 PR #477 评论）&quot;">​</a></h3><ol><li><strong>零基础设施</strong>：没有 embedding 模型、向量库、图数据库时系统必须可用——纯文本检索（BM25）兜底，embedding 只是可选增强。</li><li><strong>不为记忆等待 LLM</strong>：retrieve 路径 <strong>0 次</strong> LLM 调用；memorize <strong>至多 1 次</strong> LLM 调用且异步后台执行，永不阻塞对话。检索失败/超时 fail-open（注入空内容，对话照常）。</li><li><strong>磁盘上不允许有不可读的真相</strong>（三次修订补充）：category markdown 文件是唯一事实源；一切索引/向量都是派生缓存，删除后必须能从文件完整重建。用户和程序员看文件（和操作日志）就能知道记忆发生了什么——不需要打开任何数据库工具，更不需要 docker。</li></ol><h3 id="数据模型-resource-category-item-三层" tabindex="-1">数据模型（resource / category / item 三层） <a class="header-anchor" href="#数据模型-resource-category-item-三层" aria-label="Permalink to &quot;数据模型（resource / category / item 三层）&quot;">​</a></h3><p>对应 memU ADR-0007 的 L0 → L1 → L2 分层（见 <a href="./0002-memu-design-not-dependency.html">ADR-0002</a>）：</p><ul><li><strong>L0 resource</strong>：原始对话轮次（来源引用，metadata 记 source_conv）</li><li><strong>L1 category 文件</strong>：每个分类一个 markdown 文件（如 <code>memory/preferences.md</code>），即人工可浏览、可编辑的产物</li><li><strong>L2 item</strong>：category 文件内的条目（段落/列表项），检索与嵌入的基本单元；条目有稳定的 item-name（wiki-link 的目标），内容里带 wiki-links 与 metadata</li></ul><ol><li><strong>Categories</strong> 取代 Domain / Topic / Scene / Predicate 节点，如 <code>daily_life</code>、<code>preferences</code>、<code>personality</code>、<code>reading</code>。</li><li><strong>Wiki-links</strong> 以 <code>[[category:item-name]]</code> 格式直接写在条目内容里。检索命中条目后<strong>机械展开</strong>链接（按名字精确查找，默认一跳）拉取关联条目——不走 LLM，不建图存储。</li><li><strong>Metadata</strong> 承载结构信息（owner / source_conv / timestamp），不再需要图节点表达。</li><li><strong>单一管线，不做双模开关</strong>：LLM Mode 是唯一的运行时记忆管线；embedding 是管线内按能力启用的<strong>可选增强项</strong>（见&quot;检索&quot;节），不构成第二个模式。mem0 + Qdrant + Neo4j 一套（旧称 RAG Mode）退回 memory_bench 的本职——<strong>基准对照</strong>，迁移期保留为回退后端。</li></ol><blockquote><p>修订说明：#471 原文的&quot;LLM Mode / RAG Mode 独立开关&quot;在 2026-07-10 评审中被撤销。理由：简化后的 LLM Mode 检索（BM25 + 可选 embedding 融合）与&quot;RAG&quot;的分界线不在检索算法，而在<strong>记忆表示</strong>——把它们做成两条并行运行时管线只会重复建设。默认 LLM Mode，有 embedding 就在管线内用上，没有就纯文本检索。</p></blockquote><h3 id="写入-memorize-——每轮至多-1-次-llm-调用-异步" tabindex="-1">写入（memorize）——每轮至多 1 次 LLM 调用，异步 <a class="header-anchor" href="#写入-memorize-——每轮至多-1-次-llm-调用-异步" aria-label="Permalink to &quot;写入（memorize）——每轮至多 1 次 LLM 调用，异步&quot;">​</a></h3><p>对话轮次 → <strong>单次</strong> LLM 抽取调用（提取条目 + 归类 + 生成 wiki-links 一步完成）→ 追加/合并写入 category 文件。挂在 <code>HookPlugin.on_after_turn</code> 时机，后台执行，不阻塞下一轮对话。</p><h3 id="检索-retrieve-——0-次-llm-调用-同步但-fail-open" tabindex="-1">检索（retrieve）——0 次 LLM 调用，同步但 fail-open <a class="header-anchor" href="#检索-retrieve-——0-次-llm-调用-同步但-fail-open" aria-label="Permalink to &quot;检索（retrieve）——0 次 LLM 调用，同步但 fail-open&quot;">​</a></h3><p>同一条管线，按能力渐进增强，无模式切换：</p><table tabindex="0"><thead><tr><th>场景</th><th>排序信号</th><th>相对纯 BM25 的额外成本</th></tr></thead><tbody><tr><td>无 embedding 模型（默认 / 兜底）</td><td>BM25 关键词（中文需分词）</td><td>无</td></tr><tr><td>配置了 embedding 端点</td><td>BM25 分 + 余弦分各自 min-max 归一后融合</td><td>写入时每批条目 1 次 embedding 调用、查询时 1 次；向量存本地 memmap 缓存，规模分层见&quot;存储形态与可观测性&quot;节，无新增服务</td></tr></tbody></table><p>查询 → 检索 L2 条目 → 命中条目机械展开 wiki-links（一跳）→ 按 token 预算裁剪注入。</p><p><strong>embedding 换来什么</strong>：中文同义/改写的语义召回（&quot;想去海边&quot; vs &quot;喜欢海&quot;）——BM25 分词后仍是词面匹配。个人记忆库规模小（数千条目量级），BM25 + 良好的 item 命名可能已经够用；是否默认启用 embedding 融合，由 memory_bench probe 语料的命中率对比决定（M2 先纯 BM25 上线，融合作为 M3 可测量的可选项）。收益大于复杂度<strong>只在&quot;融合项&quot;形态下成立</strong>——一旦做成第二条管线就不成立。</p><h3 id="存储形态与可观测性-2026-07-10-三次修订-见-pr-477-评论" tabindex="-1">存储形态与可观测性（2026-07-10 三次修订，见 PR #477 评论） <a class="header-anchor" href="#存储形态与可观测性-2026-07-10-三次修订-见-pr-477-评论" aria-label="Permalink to &quot;存储形态与可观测性（2026-07-10 三次修订，见 PR #477 评论）&quot;">​</a></h3><p>评审追问：SQLite 同样是黑盒——用户/程序员无法直接看到库里发生了什么。回应：把&quot;数据库&quot;从设计里拿掉，而不是给数据库配可视化工具。</p><p><strong>磁盘上只有三种东西，全部可读或可删</strong>：</p><table tabindex="0"><thead><tr><th>磁盘产物</th><th>角色</th><th>性质</th></tr></thead><tbody><tr><td><code>memory/&lt;category&gt;.md</code></td><td><strong>唯一事实源</strong></td><td>人可读、可编辑、可 diff；用户想改记忆就改文件</td></tr><tr><td><code>journal.jsonl</code></td><td>操作日志（append-only）</td><td>每次 memorize/合并/修复一行：时间戳、source_conv、category、item-name、动作。<code>tail -f</code> 即实时视图，&quot;记忆发生了什么&quot;的完整答案</td></tr><tr><td><code>vectors.npy</code> + <code>vectors.keys.jsonl</code>（仅启用 <code>[embed]</code> 时存在）</td><td><strong>持久</strong>派生缓存</td><td>memmap 按需分页，从不整体载入 RAM；keys.jsonl 明文记录 item-name + 内容哈希（可读性由它承担，.npy 只是数字矩阵）；删除仍可重建，但重建要重调 embedding 端点（有 API 成本），故增量更新而非启动即弃</td></tr></tbody></table><p><strong>索引不落盘</strong>：BM25 索引在启动时扫描 markdown 在内存构建。数千条目量级（个人记忆库）就是几 MB 文本，重建成本可忽略；若未来到十万条量级，才允许引入磁盘缓存作为优化——仍必须满足硬约束 3（可删、可重建、非真相）。SQLite 从设计中移除（BM25 不需要它）。</p><p><strong>向量不进物理内存（四次修订，PR #477 评审）</strong>：embedding 与 BM25 索引的约束不同——全精度向量既不能常驻 RAM（100 万条 ×768 维 float32 ≈ 3 GB），也不能用 JSON 承载（文本编码体积 ×3 且必须整体 parse）。默认实现按规模分层，全部零服务、零 docker：</p><table tabindex="0"><thead><tr><th>条目规模</th><th>候选生成</th><th>常驻 RAM（768 维）</th><th>查询延迟（估，基准实测为准）</th></tr></thead><tbody><tr><td>≤ 1 万</td><td>float32 memmap 全量暴力余弦（numpy）</td><td>≈0（OS 页缓存管理热数据）</td><td>数 ms ~ 几十 ms</td></tr><tr><td>1 万 ~ 100 万</td><td>二值量化签名（1 bit/维）常驻内存 Hamming 粗排 → top-K×4 从 memmap 取全精度重排</td><td>96 B/条：10 万 ≈ 10 MB，100 万 ≈ 96 MB</td><td>&lt; 100 ms</td></tr><tr><td>超出 / 特殊需求</td><td><code>VectorIndex</code> 端口接可插拔后端（sqlite-vec、Qdrant local 等，extras 可选）</td><td>由后端决定</td><td>由后端决定</td></tr></tbody></table><ul><li><strong>端口抽象借鉴 mem0</strong>（其 VectorStore 接口 + 默认本地实现的形态）：抄接口，不抄默认值——重后端永远是宿主的选择，不是包的依赖（与 ADR-0002 同一原则在向量层的应用）。</li><li>二值量化 + 全精度重排是 Qdrant/mem0 生态的同款技术；召回损失（粗排过采样倍数）由 memory_bench probe 实测定，不拍脑袋。</li><li>numpy 归入 <code>[embed]</code> extra——纯 Python 余弦在千条以上不可接受（PR #477 评论区已修正）。</li></ul><p><strong>看见检索</strong>：<code>retrieve(..., explain=True)</code> 返回打分明细（BM25 分 / 余弦分 / 融合分、wiki-link 展开了哪些条目、token 预算裁掉了什么），适配层可直接落日志。</p><p><strong>零依赖 CLI</strong>（stdlib，随包提供）：<code>ls</code> / <code>show &lt;category&gt;</code> / <code>grep</code> / <code>explain &quot;&lt;query&gt;&quot;</code> / <code>graph --format mermaid|json</code>——最后一条从 markdown 解析 <code>[[...]]</code> 导出 wiki-link 关系图，接替 Neo4j 语义层的可视化职责（配合 #481 退役），宿主前端拿 JSON 自行渲染。全程无 docker、无服务进程。</p><p><strong>历史追溯</strong>：事实源是纯文本文件，<code>git init</code> 记忆目录即免费获得全部历史与 diff——包本身不感知 git，不强加。</p><ul><li>结构节点（Agent / Character / User / Conversation）<strong>保留</strong>，继续用于可视化</li><li>语义节点由 categories 接管，实时管线停止生成语义节点</li><li>mem0 / Neo4j 基准线退回 memory_bench 基准对照定位；embedding + graph traversal 若未来复活，以基准数据立项为研究线，不是运行时并行模式</li></ul><h2 id="理由" tabindex="-1">理由 <a class="header-anchor" href="#理由" aria-label="Permalink to &quot;理由&quot;">​</a></h2><ul><li>分类文件 + 链接是人和 LLM 都能直接阅读的组织方式；检索用纯文本搜索 + 机械链接展开，不需要向量库和图数据库</li><li>扁平存储 + metadata 让记忆条目可以直接被人工审查、编辑、diff</li><li>业界验证：memU（14k stars）最新设计（其 ADR-0007/0008）与本方案收敛到同一形态——分类 markdown 文件 + 单趟无 LLM 检索 + 无图存储，并明确放弃了多级 LLM 检索管线；wiki-links 是我们在其之上的差异化设计（memU 放弃的是实体图引擎，不是文内链接——机械展开的文内链接成本近乎为零）</li><li>放弃的备选：继续扩展 Neo4j 语义层（检索仍缺失、维护成本继续上升）；全面转向向量 RAG（丢失可解释性，且与&quot;AI 如何真的记得&quot;的探索方向不符）；LLM 多级检索管线（每轮 2–3 次 LLM 调用，延迟不可接受，memU 也已放弃该路线）</li></ul><h2 id="后果" tabindex="-1">后果 <a class="header-anchor" href="#后果" aria-label="Permalink to &quot;后果&quot;">​</a></h2><p><strong>正面</strong></p><ul><li>记忆写入链路大幅简化（不再强制走 claim 抽取 + 图谱管线）</li><li>对话零等待：读路径无 LLM 调用，写路径异步后台</li><li>无基础设施依赖：embedding / 向量库 / 图数据库都不是前提</li><li>分类体系可以由 LLM 动态扩展，无 schema 白名单</li><li>记忆内容（markdown 文件）可人工审查与编辑</li></ul><p><strong>负面 / 代价</strong></p><ul><li>无 embedding 时 BM25 对中文需要分词支持（jieba 或字符 n-gram），召回质量需要基准验证</li><li>wiki-links 的一致性需要写入侧保证（链接目标不存在时需容忍或修复）</li><li>索引不落盘意味着每次启动全量扫描重建——数千条目量级可忽略，十万条目量级需按硬约束 3 重新评估磁盘缓存</li><li>现有 claim/graph 离线管线继续保留用于 benchmark，但实时链路与它分叉，需维护两套心智模型直到语义节点退役完成</li></ul><p><strong>实施</strong></p><p>按里程碑拆分为独立 issue（挂在 <a href="https://github.com/XnneHangLab/XnneHangLab/issues/471" target="_blank" rel="noreferrer">#471</a> 下）：存储层 → wiki-link 检索 → 插件接入（默认 LLM Mode + embedding 可选融合 + mem0 迁移回退）→ Neo4j 语义节点退役。</p>',42)])])}const p=t(i,[["render",n]]);export{h as __pageData,p as default};
